            { "潘多拉|潘多拉-作用半径", ("pandoraRadius", "Pandora: effect radius (meters), default 5. Other players within range are given Pandora's Box (excluding yourself).") },
            { "潘多拉|潘多拉-拾取变魔盒概率", ("pandoraPickupToBoxChance", "Pandora: chance that any item this class picks up from the world becomes Pandora's Box (0.5 = 50%). With the remaining probability (1 − this value) the item simply disappears — i.e. \"disappear chance = 1 − this value\", the two are complementary. For example 0.5 = 50% becomes a box / 50% disappears; 0 = 100% disappears; 1 = 100% becomes a box. Items matching \"pandoraPickupBlacklist\" are unaffected. Host-only install is enough; clients need zero install.") },
            { "潘多拉|潘多拉-拾取黑名单启用", ("pandoraPickupBlacklistEnabled", "Pandora: whether to enable the \"pickup blacklist\". When on (default), items in the blacklist do not change or disappear when picked up by Pandora; when off the blacklist has no effect and every picked-up item goes through the \"become box / disappear\" check.") },
            { "潘多拉|潘多拉-拾取黑名单", ("pandoraPickupBlacklist", "Pandora: blacklist of items (prefab names, comma-separated) that are \"not affected by the Pandora effect\" when picked up. Default exclusions: PandorasBox, Flare, Amulet_Healing, Amulet_SuperJump, Amulet_Clone, Amulet_InfiniteStamina, ScoutsHonor, Mushroom Glow. Names containing spaces must be kept as-is. Leave empty for no blacklist. Only takes effect when \"pandoraPickupBlacklistEnabled\" is true.") },
            { "潘多拉|潘多拉-魔盒含自身", ("pandoraBoxIncludeSelf", "Pandora: whether the \"apply Pandora's Box every N seconds\" above also counts Pandora himself inside the effect range. false (default) = only other players within radius (excluding yourself); true = includes yourself.") },
            { "潘多拉|潘多拉-诅咒间隔", ("pandoraCurseIntervalSeconds", "Pandora: how many seconds between each stack of curse on Pandora himself (seconds), default 30.") },
            { "潘多拉|潘多拉-诅咒量", ("pandoraCurseAmount", "Pandora: amount of curse stacked on yourself each time (0.05 = 5 points). Set to 0 to disable. Note: status uses 0.025 as the minimum quantum, so increments below that value have no effect.") },
            { "死灵法师|启用职业", ("enabled", "Whether the Necromancer class is enabled.") },
            { "死灵法师|最大人数", ("maxPlayers", "Maximum number of players the Necromancer can be assigned to. Set to 0 for no limit.") },
            { "死灵法师|最小人数", ("minPlayers", "Minimum number of players the Necromancer must be assigned to. If too few, this class is filled first.") },
            { "死灵法师|抽取权重", ("weight", "Weight of the Necromancer when randomly assigning classes.") },
            { "死灵法师|骸骨-初始诅咒", ("boneInitialCurse", "Bone: initial curse at the start (0.50 = 50 points).") },
            { "死灵法师|骸骨-每层骸骨之书数", ("boneBookOfBonesPerLevel", "Bone: number of BookOfBones gained each time a new level is entered. Placed into empty slots of the player's 3 item slots first; if the inventory is full it is spawned at the player's feet and can be picked up after landing. Set to 0 to disable.") },
            { "死灵法师|骸骨-魔盒变骸骨之书", ("bonePandoraBoxToBookOfBones", "Bone: whether a PandorasBox picked up by the Necromancer turns directly into BookOfBones. Default true (on).") },
            { "死灵法师|亡灵-每死亡减诅咒", ("undeadCurseDecreasePerDeath", "Undead: curse the Necromancer loses for every 1 player death (0.05 = 5 points).") },
            { "死灵法师|亡灵-每死亡加体力", ("undeadStaminaIncreasePerDeath", "Undead: extra stamina the Necromancer gains for every 1 player death (0.20 = 20 points).") },
            { "死灵法师|亡灵-复活为人类加诅咒", ("undeadCurseIncreasePerHumanRevive", "Undead: curse the Necromancer gains for every 1 player who revives as a human (0.05 = 5 points). Set to 0 to disable.") },
            { "死灵法师|亡灵-复活为骷髅减诅咒", ("undeadCurseDecreasePerSkeletonRevive", "Undead: curse the Necromancer loses for every 1 player who revives as a skeleton (-0.10 = minus 10 points). Set to 0 to disable.") },
            { "死灵法师|亡灵-骷髅体力间隔", ("undeadSkeletonStaminaIntervalSeconds", "Undead: while there is any skeleton player on the field, how many seconds between each extra stamina gain for the Necromancer (seconds). Default 60.") },
            { "死灵法师|亡灵-每骷髅加体力", ("undeadStaminaIncreasePerSkeleton", "Undead: extra stamina the Necromancer gains per skeleton player each time (0.15 = 15 points). Stacks linearly with the number of skeletons on the field.") },
            { "死灵法师|亡灵-骷髅减诅咒间隔", ("undeadSkeletonCurseIntervalSeconds", "Undead: while there is any skeleton player on the field, how many seconds between each curse decrease for the Necromancer (seconds). Default 180 (3 minutes).") },
            { "死灵法师|亡灵-每骷髅减诅咒", ("undeadCurseDecreasePerSkeleton", "Undead: curse the Necromancer loses per skeleton player each time (-0.025 = minus 2.5 points). Stacks linearly with the number of skeletons on the field. Note: status uses 0.025 as the minimum quantum, so increments below that value have no effect.") },
            { "死灵法师|亡灵-光环间隔", ("undeadAuraIntervalSeconds", "Undead: interval (seconds) at which the Necromancer applies the aura effect to players within radius. Default 5. Set to 0 to disable.") },
            { "死灵法师|亡灵-光环半径", ("undeadAuraRadius", "Undead: aura radius (meters), centered on the Necromancer himself (excluding self). Default 15.") },
            { "死灵法师|亡灵-光环人类中毒", ("undeadAuraHumanPoison", "Undead: poison added by each aura tick to human players within radius (0.025 = 2.5 points). Set to 0 to disable.") },
            { "死灵法师|亡灵-光环骷髅体力", ("undeadAuraSkeletonStamina", "Undead: extra stamina added by each aura tick to skeleton players within radius (0.025 = 2.5 points). Set to 0 to disable.") },
            { "死灵法师|亡灵-光环无敌间隔", ("undeadAuraInvincibilityIntervalSeconds", "Undead: how many seconds between applying an invincibility effect (FortifiedMilk) to skeleton players within the aura radius (excluding the Necromancer himself). Default 10. Set to 0 or negative to disable. It counts independently from \"undeadAuraIntervalSeconds\" and is limited by \"undeadAuraRadius\"; human players are unaffected by this entry.") },
            { "M|启用职业", ("enabled", "Whether the M class is enabled.") },
            { "M|最大人数", ("maxPlayers", "Maximum number of players M can be assigned to. Set to 0 for no limit.") },
            { "M|最小人数", ("minPlayers", "Minimum number of players M must be assigned to. If too few, this class is filled first.") },
            { "M|抽取权重", ("weight", "Weight of M when randomly assigning classes.") },
            { "M|享受-倍率", ("enjoyMultiplier", "Enjoy: multiplier for the extra stamina M gains for every 1 point of the following negative statuses (default 1 = equal amount). Covered negative statuses: injury, poison, spores, thorns, burn, frostbite, webbing, arrow, flytrap. For example 1 = taking 5 points of injury grants 5 points of extra stamina; 2 = grants 10 points; set to 0 to disable this effect.") },
            { "M|享受-检测间隔", ("enjoyCheckIntervalSeconds", "Enjoy: how many seconds between each check of your own status (seconds). Default 60. If at the time of the check you have none of the following specific negative statuses, the extra stamina from \"enjoyNoStatusDeduction\" is deducted. Specific negative statuses: injury, poison, spores, thorns, burn, frostbite, webbing, arrow, flytrap. Set to 0 to disable this effect.") },
            { "M|享受-无状态扣除", ("enjoyNoStatusDeduction", "Enjoy: extra stamina deducted when the check above finds \"no specific negative status\" (0.10 = 10 points). Default 10 points. Extra stamina has a lower bound of 0 and will not go negative. Set to 0 to disable this effect.") },
            { "M|耐受-启用", ("toleranceEnabled", "Tolerance: whether the \"Tolerance\" effect is enabled. Default true.") },
            { "M|耐受-间隔", ("toleranceIntervalSeconds", "Tolerance: how many seconds between each reduction of the following specific negative statuses (seconds). Default 10.") },
            { "M|耐受-削减量", ("toleranceReduction", "Tolerance: amount of the specific negative statuses reduced each time (0.05 = 5 points). Default 5 points. Set to 0 to disable. Covers: injury, poison, spores, thorns, burn, frostbite. Note: thorns is a hard exclusion of the vanilla \"status array channel\" and is only actually reduced when M is the host himself (see technical doc §3.9).") },
            { "野人|启用职业", ("enabled", "Whether the Savage class is enabled.") },
            { "野人|最大人数", ("maxPlayers", "Maximum number of players the Savage can be assigned to. Set to 0 for no limit.") },
            { "野人|最小人数", ("minPlayers", "Minimum number of players the Savage must be assigned to. If too few, this class is filled first.") },
            { "野人|抽取权重", ("weight", "Weight of the Savage when randomly assigning classes.") },
            { "野人|自然韧性-触发间隔", ("naturalTenacityIntervalSeconds", "Natural Toughness: how many seconds between each clearing of poison and spores for the Savage (seconds). Default 5.") },
            { "野人|自然韧性-中毒量", ("naturalTenacityPoison", "Natural Toughness: amount of poison cleared each time (0.025 = 2.5 points, the engine's minimum effective step). Set to 0 to disable.") },
            { "野人|自然韧性-孢子量", ("naturalTenacitySpores", "Natural Toughness: amount of spores cleared each time (0.025 = 2.5 points). Set to 0 to disable.") },
            { "野人|野性未泯-损伤", ("wildnessInjury", "Wildness: injury the Savage gains when eating \"packaged food\" or \"cooked food\" (0.05 = 5 points). Judged by game item tags: packaged food = PackagedFood; cooked food = CookedAmount ≥ 1. Natural food (berries, mushrooms, raw ingredients, etc.) does not trigger this unless cooked; set to 0 to disable the effect. (Mushroom Glow, Energy Drink, FortifiedMilk and Lollipop are excluded.)") },
            { "野人|野性未泯-烤熟自然食物触发", ("wildnessCookedNaturalFoodTrigger", "Wildness: whether natural food (berries, mushrooms, etc.) also triggers the HP loss once it is cooked. On (default): triggers as long as the item has been cooked (CookedAmount ≥ 1), matching the original meaning of \"cooked food\". Off: only vanilla \"Gourmand\" type food (with the GourmandRequirement tag) triggers when cooked, and cooked natural food does not trigger (old behaviour).") },
            { "野人|野性未泯-黑名单", ("wildnessBlacklist", "Wildness: eating these items does not trigger the HP loss (prefab names, comma-separated). Default: Mushroom Glow, Energy Drink, FortifiedMilk, Lollipop. Leave empty for no blacklist (in that case only tag checks such as \"natural food\" apply).") },
            { "野人|不拿拿-触发间隔", ("bananaIntervalSeconds", "Banana: how many seconds between each grant of a pink banana to the Savage (seconds). Default 60.") },
            { "野人|不拿拿-物品", ("bananaItem", "Banana: prefab name of the granted item. Default Berrynana Pink = pink banana. If wrong or empty, nothing is granted.") },
            { "野人|不拿拿-数量", ("bananaCount", "Banana: number granted each time. Placed into empty inventory slots first; if the inventory is full it is spawned at your feet. Set to 0 to disable.") },
            { "野人|知识污染-目标物品", ("knowledgePollutionTargetItem", "Knowledge Pollution: the source item that hits is replaced directly with this item (enter the prefab name). Default FireWood = stick.") },
            { "野人|知识污染-来源物品", ("knowledgePollutionSourceItems", "Knowledge Pollution: prefab names of the source items that get replaced with the \"target item\", comma-separated. Default: ClimbingSpike, RopeShooter, ChainShooter, RescueHook, AntiZooka.") },
            { "童军|启用职业", ("enabled", "Whether the Scout class is enabled. Default true. Scout's \"Luggage\" starts with a \"Fannypack (containing 2 random items)\"; when alone, \"Collective\" is a pure penalty and only turns into a benefit when other players, or other Scouts/Leaders, are nearby.") },
            { "童军|最大人数", ("maxPlayers", "Maximum number of players the Scout can be assigned to. Set to 0 for no limit. Default 4. Note: the tier-2/3 bonuses require other players, or other Scouts/Leaders, within the radius.") },
            { "童军|最小人数", ("minPlayers", "Minimum number of players the Scout must be assigned to. If too few, this class is filled first. Default 0 (not enforced).") },
            { "童军|抽取权重", ("weight", "Weight of the Scout when randomly assigning classes.") },
            { "童军|行李-启用", ("luggageEnabled", "\"Luggage\": whether enabled. Default true.") },
            { "童军|行李-背包", ("luggageBackpack", "\"Luggage\": prefab name of the backpack equipped directly on the Scout at the start. Default Fannypack = funny backpack. If wrong or empty, it falls back to the default Backpack.") },
            { "童军|行李-物品数", ("luggageItemCount", "\"Luggage\": number of random items placed in the backpack (non-repeating). Default 2. Setting 0 gives only an empty backpack.") },
            { "童军|行李-物品池", ("luggageItemPool", "\"Luggage\": candidate pool of random items in the backpack (prefab names, comma-separated, 33 entries in total). Corresponds to: ScoutCookies / Lollipop / Airplane Food / Glizzy / Marshmallow / TrailMix / Granola Bar / Winterberry Yellow / Apple Berry Red / Berrynana Yellow / NestEgg_Raven / Energy Drink / Sports Drink / RopeSpool / FortifiedMilk / Bandages / FirstAidKit / Balloon / BalloonBunch / Glider / Parachute / Parasol / Flare / Lantern / Pirate Compass / Binoculars / Basketball / Compass / Frisbee / Torch / Stone / Passport / BingBong. ⚠ The prefab names for \"Glider / Flare\" could not be confirmed from the available decompiled material, so Glider / Flare are used for now; if they fail to spawn in testing (the log will say the name was not found), replace these two with the real prefab names.") },
            { "童军|集体-半径", ("collectiveRadius", "\"Collective\": radius (meters) for judging \"other players / Scouts or Leaders nearby\". Default 15.") },
            { "童军|集体-独自间隔", ("collectiveAloneIntervalSeconds", "\"Collective·Alone\": when there are no other players within the radius, how many seconds between each stack of injury and hunger on the Scout (seconds). Default 20.") },
            { "童军|集体-独自损伤", ("collectiveAloneInjury", "\"Collective·Alone\": injury added each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "童军|集体-独自饥饿", ("collectiveAloneHunger", "\"Collective·Alone\": hunger added each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "童军|集体-同伴损伤间隔", ("collectiveCompanionInjuryIntervalSeconds", "\"Collective·Companion\": when there are other players (but none of them Scouts or Leaders) within the radius, how many seconds between each injury reduction (seconds). Default 20.") },
            { "童军|集体-同伴减损伤", ("collectiveCompanionInjuryReduction", "\"Collective·Companion\": injury reduced each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "童军|集体-同伴饥饿间隔", ("collectiveCompanionHungerIntervalSeconds", "\"Collective·Companion\": how many seconds between each hunger reduction (seconds). Default 50.") },
            { "童军|集体-同伴减饥饿", ("collectiveCompanionHungerReduction", "\"Collective·Companion\": hunger reduced each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "童军|集体-童军损伤间隔", ("collectiveScoutInjuryIntervalSeconds", "\"Collective·Scout/Leader\": when there are other Scouts or Leaders within the radius, how many seconds between each injury reduction (seconds). Default 15.") },
            { "童军|集体-童军减损伤", ("collectiveScoutInjuryReduction", "\"Collective·Scout/Leader\": injury reduced each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "童军|集体-童军饥饿间隔", ("collectiveScoutHungerIntervalSeconds", "\"Collective·Scout/Leader\": how many seconds between each hunger reduction (seconds). Default 30.") },
            { "童军|集体-童军减饥饿", ("collectiveScoutHungerReduction", "\"Collective·Scout/Leader\": hunger reduced each time (0.025 = 2.5 points). Set to 0 to disable this entry.") },
            { "旗手|启用职业", ("enabled", "Whether the Standard Bearer class is enabled.") },
            { "旗手|最大人数", ("maxPlayers", "Maximum number of players the Standard Bearer can be assigned to. Set to 0 for no limit.") },
            { "旗手|最小人数", ("minPlayers", "Minimum number of players the Standard Bearer must be assigned to. If too few, this class is filled first.") },
            { "旗手|抽取权重", ("weight", "Weight of the Standard Bearer when randomly assigning classes.") },
            { "旗手|执旗-每层旗标数", ("flagCountPerLevel", "Flag: number of Flag_Plantable_Checkpoint gained each time a new level is entered. Placed into empty slots of the player's 3 item slots first; if the inventory is full it is spawned at the player's feet and can be picked up after landing. Set to 0 to disable.") },
            { "旗手|执旗-触发延迟", ("flagTriggerDelay", "Flag: how many seconds after planting a flag before the effect is applied (seconds). Default 3.") },
            { "旗手|执旗-效果数量下限", ("flagEffectCountMin", "Flag: minimum number of random effects each living player gains per flag planted (1~3). Default 1.") },
            { "旗手|执旗-效果数量上限", ("flagEffectCountMax", "Flag: maximum number of random effects each living player gains per flag planted (1~3). Default 3. The three effects (infinite stamina / speed boost / invincibility) can stack at the same time. If the minimum or maximum is 0 it is forced into the 1~3 range.") },
            { "旗手|执旗-无限体力权重", ("flagInfiniteStaminaWeight", "Flag: weight of the random effect \"infinite stamina (Lollipop)\". Set to 0 to exclude this effect from the draw. Note: after Lollipop's infinite stamina ends, drowsy is stacked \"continuously\" via the vanilla Affliction_AdjustDrowsyOverTime (measured at about 32.5 points); on the client this drowsy can never fade naturally because the continuous stacking keeps refreshing LastAddedStatus, so the host clears it after this effect ends (see \"flagInfiniteStaminaClearDrowsy\").") },
            { "旗手|执旗-加速权重", ("flagSpeedBoostWeight", "Flag: weight of the random effect \"speed boost (Energy Drink)\". Set to 0 to exclude this effect from the draw.") },
            { "旗手|执旗-无敌权重", ("flagInvincibilityWeight", "Flag: weight of the random effect \"invincibility (FortifiedMilk)\". Set to 0 to exclude this effect from the draw.") },
            { "旗手|执旗-加速-清除困倦", ("flagSpeedBoostClearDrowsy", "Flag: after Energy Drink's speed boost ends and the player is given drowsy, the amount of drowsy the host sends to offset it (0.25 = 25 points). Same idea as the Explorer's \"hypermetabolismClearDrowsyAfterSprint\": the boost duration is decided by Energy Drink itself (about 10 seconds) and the host cannot rewrite it. Set to 0 to disable the clearing.") },
            { "旗手|执旗-无限体力-清除困倦", ("flagInfiniteStaminaClearDrowsy", "Flag: after Lollipop's infinite stamina ends and its follow-up \"continuous drowsy stacking\" affliction also ends, the amount of drowsy the host sends to offset it (0.35 = 35 points, covering the measured about 32.5 points). Rationale: this \"continuous stacking\" adjusts drowsy every frame on the client and refreshes LastAddedStatus(Drowsy), so drowsy never meets the natural-fade condition (it shows as \"drowsy value stays unchanged\"); and it only starts stacking after infinite stamina ends, so it must be cleared only after it ends. The host determines the timing by observing this affliction (DrowsyOverTime) change from present to absent. Set to 0 to disable the clearing.") },
            { "旗手|执旗-净化半径", ("flagPurifyRadius", "Flag: radius (meters) within which planting a flag \"immediately\" clears all negative statuses from all players. Default 15. The negative statuses cleared are \"injury / hunger / cold / poison / drowsy / overheating / spores / webbing / flytrap\", and do not include curse or petrify. Set to 0 to disable purification. (Crab / weight / thorns / arrow are uncleansable, consistent with vanilla, as they fall under the game's original \"unhealable\" rule.)") },
            { "旗手|执旗-净化含自身", ("flagPurifyIncludeSelf", "Flag: whether purification also affects the flag planter himself. Default true (includes self).") },
            { "旗手|执旗-插旗石化", ("flagPlantPetrify", "Flag: the extra petrify applied to the Standard Bearer \"himself\" when a flag is planted and purification runs (0.20 = 20 points). Default 0.20. This petrify is the cost of the purification effect and is not cleared by the same purification round (purification already excludes curse and petrify). Set to 0 to disable.") },
            { "舞王|启用职业", ("enabled", "Whether the Dancer class is enabled.") },
            { "舞王|最大人数", ("maxPlayers", "Maximum number of players the Dancer is assigned to. Set to 0 for no limit.") },
            { "舞王|最小人数", ("minPlayers", "Minimum number of players the Dancer is assigned to. When there are too few players, this class is prioritized to fill up.") },
            { "舞王|抽取权重", ("weight", "Weight for the Dancer to be drawn during random assignment.") },
            { "舞王|舞动青春-半径", ("danceYouthRadius", "Dance Youth: radius (meters) for judging \"how close to the Dancer a player must be to count as dancing\". Default 15.") },
            { "舞王|舞动青春-额外体力", ("danceYouthExtraStamina", "Dance Youth: when 1 player within the radius dances, the extra stamina added to both the Dancer and that dancing player (0.025 = 2.5 points). Set to 0 to disable this effect.") },
            { "舞王|舞动青春-检测冷却", ("danceYouthCheckCooldown", "Dance Youth: after one dance is detected, how many seconds that player's further dancing won't trigger this bonus again (seconds). Default 1.") },
            { "舞王|全场欢呼-半径", ("fullCheerRadius", "Full Cheer: when the Dancer itself dances, forces all other living players within this radius (meters) to dance together. Default 15.") },
            { "舞王|狂热舞者-间隔", ("fanaticDancerInterval", "Fanatic Dancer: how many seconds between forcing the Dancer itself to backflip (seconds). Default 120. The backflip is the vanilla emote A_Scout_Emote_BackFlip, and after the flip the player falls down for about 1 second; this action is not \"dancing\" and will not trigger \"Dance Youth\" or \"Full Cheer\". Set to 0 or negative to disable.") },
            { "舞王|跳舞动作名", ("danceActionNames", "Animation names of the dance action (multiple names can be filled separated by commas); the host's \"force dance\" uses the first item in the list. Default A_Scout_Emote_Dance1 (verified to work); in addition, any emote name containing dance (case-insensitive) is also treated as dancing, so in most cases no change is needed. If no action is visible when force-dancing: manually perform a dance emote in game, then search the log for \"舞王·观测到表情\" to find the actual animation name, and fill it here (put it first).") },
            { "待皓|启用职业", ("enabled", "Whether the Daihao class is enabled.") },
            { "待皓|最大人数", ("maxPlayers", "Maximum number of players Daihao is assigned to. Set to 0 for no limit.") },
            { "待皓|最小人数", ("minPlayers", "Minimum number of players Daihao is assigned to. When there are too few players, this class is prioritized to fill up.") },
            { "待皓|抽取权重", ("weight", "Weight for Daihao to be drawn during random assignment.") },
            { "待皓|化身-启用", ("avatarEnabled", "Avatar: whether to replace the Daihao player's outfit with the style specified below for this round. false = don't change the outfit at all. Only applied when the player's class is Daihao; when the player is no longer Daihao (e.g. leaves via class change), their original outfit is restored immediately.") },
            { "待皓|化身-皮肤", ("avatarSkin", "Avatar: skin color ID. Default 0 (Daihao set). -1 = keep the player's original skin.") },
            { "待皓|化身-眼睛", ("avatarEyes", "Avatar: eyes ID. Default 3 (Daihao set). -1 = keep the player's original eyes.") },
            { "待皓|化身-嘴巴", ("avatarMouth", "Avatar: mouth ID. Default 6 (Daihao set). -1 = keep the player's original mouth.") },
            { "待皓|化身-饰品", ("avatarAccessory", "Avatar: accessory ID. Default 8 (Daihao set). -1 = keep the player's original accessory.") },
            { "待皓|化身-服装", ("avatarOutfit", "Avatar: outfit ID. Default 25 (Daihao set). -1 = keep the player's original outfit.") },
            { "待皓|化身-帽子", ("avatarHat", "Avatar: hat ID. Default 25 (Daihao set). -1 = keep the player's original hat.") },
            { "待皓|化身-腰带", ("avatarBelt", "Avatar: belt ID. Default -1 = keep the player's original belt.") },
            { "待皓|化身-奖章", ("avatarBadge", "Avatar: badge ID. Default -1 = keep the player's original badge.") },
            { "待皓|化身-监控时长", ("avatarMonitorDuration", "Avatar: the self-healing monitoring duration (seconds) during which, after applying, it keeps comparing every second and re-sends if overwritten. Default 15. The target player's own client asynchronously reads the Steam outfit after the character is instantiated and broadcasts another copy of the real outfit; if it arrives later than this effect it will overwrite the avatar back (shown as \"not taking effect at the start, only taking effect after leaving and returning to the class\"). So for a period after the player is assigned as Daihao, it checks once per second and self-heals by re-sending; after the window ends it no longer checks. Set to 0 or negative = disable self-healing (apply only once).") },
            { "待皓|喂喂喂-检测间隔", ("helloHelloCheckInterval", "Hello Hello, Can You Hear Me: how many seconds between checks of the Daihao player's voice status (seconds). Default 60. The check is based on the in-game \"actually speaking\" judgement (with a noise threshold; merely having the mic on without speaking doesn't count), and extra stamina is only added if the player is actually speaking at that exact moment. Set to 0 or negative to disable.") },
            { "待皓|喂喂喂-额外体力", ("helloHelloExtraStamina", "Hello Hello, Can You Hear Me: the extra stamina added to that Daihao player when speaking is detected (0.1 = 10 points). Set to 0 to disable this effect.") },
            { "待皓|脚滑-触发间隔", ("slipTriggerInterval", "Slippery Feet: how many seconds between forcing the Daihao player to backflip (seconds). Default 150. The backflip is the vanilla emote A_Scout_Emote_BackFlip, and the player always falls down after the flip (down for about 1 second). Set to 0 or negative to disable.") },
            { "待皓|生产-物品", ("produceItem", "Produce: item prefab name granted periodically. Default NestEgg (a big egg that yields a fried egg Egg when smashed open).") },
            { "待皓|生产-发放间隔", ("produceGrantInterval", "Produce: how many seconds between granting 1 \"Produce-Item\" to each Daihao player (seconds). Default 120. Grants are put into the 3 free inventory slots first; when all three slots are full it spawns at the player's feet (pickable up after landing). Set to 0 or negative to disable granting.") },
            { "待皓|生产-体力间隔", ("produceStaminaInterval", "Produce: when any of the Daihao player's 3 inventory slots contains the \"Produce-Item\", how many seconds between adding extra stamina once (seconds). Default 60. Set to 0 or negative to disable.") },
            { "待皓|生产-额外体力", ("produceExtraStamina", "Produce: the extra stamina added each time a \"Produce-Item\" is detected in the inventory (0.05 = 5 points). Set to 0 to disable.") },
            { "待皓|模因污染-启用", ("memePollutionEnabled", "Meme Pollution: when a Daihao class player exists in this round, other players who eat the \"Meme Pollution-Trigger Item\" will directly change class into Daihao. Default true. To change class, that player must not already be Daihao. Note: this class change bypasses the \"maxPlayers\" limit (otherwise this effect could never trigger once Daihao has reached its limit).") },
            { "待皓|模因污染-触发物品", ("memePollutionTriggerItem", "Meme Pollution: item prefab name that triggers the class change (comma-separated, multiple allowed). Default Egg (fried egg, produced by smashing open the big egg NestEgg). Note: the big egg NestEgg itself is a smashable egg and doesn't go through the eating channel, so the trigger can only be the fried egg Egg it yields.") },
            { "待皓|我们全都是-半径", ("weAreAllRadius", "We Are All: counting radius (meters). Default 50.") },
            { "待皓|我们全都是-触发间隔", ("weAreAllTriggerInterval", "We Are All: how many seconds between settlements (seconds). Default 30. Set to 0 or negative to disable this effect.") },
            { "待皓|我们全都是-减损伤", ("weAreAllInjuryReduction", "We Are All: for each other Daihao besides yourself within the radius, the injury reduced (healed) at this settlement (0.025 = 2.5 points). Default 0.025, i.e. every 30 seconds heal yourself by \"number of other Daihao × 2.5 points\". Set to 0 to disable this effect.") },
            { "圣人|启用职业", ("enabled", "Whether the Saint class is enabled.") },
            { "圣人|最大人数", ("maxPlayers", "Maximum number of players the Saint is assigned to. Set to 0 for no limit.") },
            { "圣人|最小人数", ("minPlayers", "Minimum number of players the Saint is assigned to. When there are too few players, this class is prioritized to fill up.") },
            { "圣人|抽取权重", ("weight", "Weight for the Saint to be drawn during random assignment.") },
            { "圣人|教诲-触发间隔", ("teachingTriggerInterval", "Teaching: how many seconds between applying a bonus to other players within the radius (seconds). Default 10.") },
            { "圣人|教诲-半径", ("teachingRadius", "Teaching: effect radius (meters). Default 10. Other players within range are buffed (excluding yourself).") },
            { "圣人|教诲-额外体力", ("teachingExtraStamina", "Teaching: the extra stamina added to each other player within the radius each time (0.025 = 2.5 points). Set to 0 to disable this item.") },
            { "圣人|教诲-困倦", ("teachingDrowsy", "Teaching: the drowsy added to each other player within the radius each time (0.10 = 10 points). Set to 0 to disable this item. Note: statuses use 0.025 as the minimum quantum, so increments below that value have no effect.") },
            { "圣人|完美主义-触发间隔", ("perfectionismTriggerInterval", "Perfectionism: how many seconds between adding extra stamina to the Saint itself (seconds). Default 60.") },
            { "圣人|完美主义-额外体力", ("perfectionismExtraStamina", "Perfectionism: the extra stamina added to the Saint itself each time (1 = 100 points). Set to 0 to disable this item.") },
            { "圣人|完美主义-拾取消失概率", ("perfectionismPickupVanishChance", "Perfectionism: when the Saint picks up an item from the world, the chance that the item directly disappears (1 = 100%). Items matching \"Perfectionism-Pickup Blacklist\" are not affected (they go into the pack as normal). Takes effect only when installed on the host; zero install on clients.") },
            { "圣人|完美主义-拾取黑名单", ("perfectionismPickupBlacklist", "Perfectionism: blacklist of items (prefab names, comma-separated) that are \"not affected by Perfectionism (won't disappear)\" when picked up. Default excluded: Mushroom Glow, Flare, Amulet_Healing, Amulet_SuperJump, Amulet_Clone, Amulet_InfiniteStamina, ScoutsHonor. Names containing spaces must be kept as-is. Leave blank to set no blacklist.") },
            { "圣人|辟谷养生-饥饿", ("fastingHunger", "Fasting: the hunger cleared for the Saint each time a new level is entered (1 = 100 points, i.e. empties hunger). This value is positive, meaning the amount of hunger to \"subtract\"; set to 0 to disable this item.") },
            { "圣人|辟谷养生-无敌", ("fastingInvincible", "Fasting: besides clearing hunger, whether an invincibility effect is additionally applied to the Saint each time a new level is entered (FortifiedMilk). Default true. Only settled when \"Fasting-Hunger\" > 0.") },
            { "圣人|超然物外-启用", ("detachmentEnabled", "Detachment: whether the Saint is immune to the following negative effects imposed by other classes. Default true. Immunity scope: (1) Pandora's Child · Pandora (won't be afflicted with Pandora's Box while within Pandora's range); (2) Necromancer · Undead · Aura (as a human player won't gain injury from the aura; the skeleton form's stamina bonus is unaffected); (3) Dancer · Full Cheer (won't be forced to dance along when the Dancer dances).") },
            { "圣人|跌落神坛-检测间隔", ("fallenFromAltarCheckInterval", "Fall from the Altar: how many seconds between checks of whether the Saint itself has taken injury (seconds). Default 1.") },
            { "圣人|跌落神坛-损伤", ("fallenFromAltarInjury", "Fall from the Altar: when the Saint itself is detected to have increased injury during this interval, the additional injury appended (1 = 100 points). This effect is extremely lethal and interacts with the injury it appends itself; set to 0 to disable.") },
            { "法师|启用职业", ("enabled", "Whether the Mage class is enabled.") },
            { "法师|最大人数", ("maxPlayers", "Maximum number of players the Mage is assigned to. Set to 0 for no limit.") },
            { "法师|最小人数", ("minPlayers", "Minimum number of players the Mage is assigned to. When there are too few players, this class is prioritized to fill up.") },
            { "法师|抽取权重", ("weight", "Weight for the Mage to be drawn during random assignment.") },
            { "法师|卷轴-发放间隔", ("scrollGrantInterval", "Magic Scroll: how many seconds between granting 1 scroll to each Mage (seconds). Default 180 (3 minutes). Grants are put into the 3 free inventory slots first; when all three slots are full it spawns at the mage's feet (pickable up after landing). Set to 0 or negative to disable granting.") },
            { "法师|卷轴-物品", ("scrollItem", "Magic Scroll: item prefab name for the scroll. Default GuidebookPageScroll Variant (a scroll that turns into a tutorial page after use).") },
            { "法师|卷轴-延迟", ("scrollDelay", "Magic Scroll: in human form, how many seconds after opening the scroll before the random effect triggers (seconds). Default 3.") },
            { "法师|卷轴-人类石化", ("scrollHumanPetrify", "Magic Scroll: the petrify added to the Mage itself each time a scroll is opened in human form (0.05 = 5 points). Set to 0 to disable.") },
            { "法师|卷轴-骷髅诅咒", ("scrollSkeletonCurse", "Black Magic: the curse added to the Mage itself each time a scroll is opened in skeleton form (0.05 = 5 points). Set to 0 to disable.") },
            { "法师|卷轴-连锁概率", ("scrollChainChance", "Black Magic: after triggering 1 effect, the chance to trigger the next effect again (0~1). Default 0.30 (30%). After each chain trigger, this chance is re-rolled to decide whether to continue; set to 0 to trigger only 1 effect at a time.") },
            { "法师|卷轴-连锁间隔", ("scrollChainInterval", "Black Magic: when chain-triggering, the delay of the next effect relative to the previous one (seconds). Default 1. Used to avoid triggering too many effects at once and to reduce instantaneous performance cost. Set to 0 to settle continuously almost immediately (about the next frame).") },
            { "法师|强化-半径", ("enhanceRadius", "[Enhance] effect radius (meters), including yourself. Default 15.") },
            { "法师|激化-半径", ("intensifyRadius", "[Intensify] effect radius (meters), including yourself. Default 15.") },
            { "法师|固化-半径", ("solidifyRadius", "[Solidify] effect radius (meters), including yourself. Default 15.") },
            { "法师|点化-半径", ("enlightenRadius", "[Enlighten] effect radius (meters). Default 10. Excludes yourself.") },
            { "法师|点化-额外体力", ("enlightenExtraStamina", "[Enlighten] the extra stamina added to each player within the radius each time (0.5 = 50 points). Set to 0 to disable this item.") },
            { "法师|净化-半径", ("purifyRadius", "[Purify] effect radius (meters), including yourself. Default 10.") },
            { "法师|净化-时长", ("purifyDuration", "[Purify] duration (seconds). Default 5. During it, negative statuses are reduced by \"Purify-Per Second\" every second.") },
            { "法师|净化-每秒", ("purifyPerSecond", "[Purify] the amount of negative status cleared for each player within the radius per second (0.025 = 2.5 points). Applies to curable negative statuses (injury/hunger/cold/poison/drowsy/hot/spores/web/venus flytrap). Set to 0 to disable.") },
            { "法师|治愈-半径", ("healRadius", "[Heal] effect radius (meters), including yourself. Default 15.") },
            { "法师|治愈-时长", ("healDuration", "[Heal] duration (seconds). Default 10. During it, injury is reduced by \"Heal-Per Second\" every second.") },
            { "法师|治愈-每秒", ("healPerSecond", "[Heal] the amount of injury cleared for each player within the radius per second (0.025 = 2.5 points). Set to 0 to disable.") },
            { "法师|反重-半径", ("antiGravityRadius", "[Anti-Gravity] effect radius (meters), including yourself. Default 20.") },
            { "法师|反重-时长", ("antiGravityDuration", "[Anti-Gravity] duration (seconds). Default 10. During it, 1 anti-gravity field is spawned at the feet every \"Anti-Gravity-Interval\" seconds.") },
            { "法师|反重-间隔", ("antiGravityInterval", "[Anti-Gravity] how many seconds between spawning 1 anti-gravity field at the feet of each player within the radius (seconds). Default 5.") },
            { "法师|反重-预制体", ("antiGravityPrefab", "[Anti-Gravity] prefab name of the anti-gravity field spawned each time. Default AntiSphere (the same prefab as the anti-gravity field spawned by firing the anti-gravity cannon). Leave blank to make this effect fail. Implementation: the prefab's registered in-game name is first looked up and resolved in the scene, and only falls back to this configured name if not found.") },
            { "法师|传送-半径", ("teleportRadius", "[Teleport] selection radius (meters) of the players to be teleported, including yourself. Default 10.") },
            { "法师|传送-最小距离", ("teleportMinDistance", "[Teleport] minimum distance (meters) between the target player and the Mage. Default 50. I.e. teleports players within the radius to a random player \"more than 50 meters away from the Mage\".") },
            { "法师|复活-距离", ("reviveDistance", "[Resurrect]/[Soul Return] when reviving a player, the offset distance (meters) of the revive point relative to the Mage. Default 1.5 (i.e. \"beside yourself\").") },
            { "法师|血祭-半径", ("bloodSacrificeRadius", "[Blood Sacrifice] effect radius (meters). Default 15.") },
            { "法师|血祭-人类损伤", ("bloodSacrificeHumanInjury", "[Blood Sacrifice] the injury added to each human player within the radius (0.10 = 10 points). Set to 0 to disable.") },
            { "法师|血祭-人类体力", ("bloodSacrificeHumanStamina", "[Blood Sacrifice] the extra stamina added to each human player within the radius (0.20 = 20 points). Set to 0 to disable.") },
            { "法师|血祭-自身每人诅咒", ("bloodSacrificeSelfPerPlayerCurse", "[Blood Sacrifice] for each 1 player affected, the curse added to the Mage itself (0.025 = 2.5 points). Set to 0 to disable.") },
            { "法师|血祭-自身每人体力", ("bloodSacrificeSelfPerPlayerStamina", "[Blood Sacrifice] for each 1 player affected, the extra stamina added to the Mage itself (0.25 = 25 points). Set to 0 to disable.") },
            { "法师|献祭-半径", ("sacrificeRadius", "[Sacrifice] effect radius (meters). Default 15.") },
            { "法师|献祭-物品", ("sacrificeItem", "[Sacrifice] item prefab name \"used\" on a random 1 player within the radius. Default Cursed Skull. Implementation: the host spawns the item and hands it to the target player to use via the vanilla feeding channel. Leave blank and this effect only buffs yourself and doesn't affect the target.") },
            { "法师|献祭-自身诅咒", ("sacrificeSelfCurse", "[Sacrifice] the curse added to the Mage itself (0.05 = 5 points). Set to 0 to disable.") },
            { "法师|易位-最小距离", ("swapMinDistance", "[Swap] minimum distance (meters) between the target player whose position is swapped and the Mage. Default 50. If no qualifying player exists, gain 1 Quqian Mushroom instead.") },
            { "法师|天灾-存在时长", ("calamityDuration", "[Calamity] tornado existence duration (seconds); destroyed by the host when it expires. Default 5.") },
            { "法师|虫灾-半径", ("insectPlagueRadius", "[Insect Plague] effect radius (meters), including yourself. Default 15.") },
            { "法师|虫灾-生成高度", ("insectPlagueSpawnHeight", "[Insect Plague] the height (meters) at which beetles spawn \"above the head\" of each player. Default 2.5.") },
            { "法师|尸变-半径", ("zombifyRadius", "[Zombify] effect radius (meters), excluding yourself. Default 15.") },
            { "法师|尸变-孢子", ("zombifySpores", "[Zombify] the spores added to a random 1 human player within the radius (1 = 100 points). Set to 0 to disable.") },
            { "法师|尸变-自身诅咒", ("zombifySelfCurse", "[Zombify] the curse added to the Mage itself (0.025 = 2.5 points). Set to 0 to disable.") },
            { "法师|尸变-僵尸距离", ("zombifyZombieDistance", "[Zombify] when there is no qualifying human player within the radius, spawn 1 zombie \"how many meters away\" from the Mage instead. Default 3.") },
            { "法师|还魂-领队距离", ("soulReturnLeaderDistance", "[Soul Return] when there is no dead player to revive, spawn 1 Scout Leader \"how many meters in front of\" the Mage (meters). Default 10.") },
            { "法师|还魂-追击时间", ("soulReturnChaseDuration", "[Soul Return] duration (seconds) for which the Scout Leader is forced to chase the Mage. Default 15; after the timeout the leader stops chasing and leaves on its own (same as the vanilla loudspeaker mechanic).") },
            { "法师|反噬-半径", ("backlashRadius", "[Backlash] effect radius (meters), including yourself. Default 15.") },
            { "法师|反噬-诅咒", ("backlashCurse", "[Backlash] the curse added to each player within the radius (0.10 = 10 points). Set to 0 to disable.") },
            { "法师|反噬-石化", ("backlashPetrify", "[Backlash] the petrify added to each player within the radius (0.10 = 10 points). Set to 0 to disable.") },
            { "法师|权重-强化", ("weightEnhance", "[Enhance] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-激化", ("weightIntensify", "[Intensify] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-固化", ("weightSolidify", "[Solidify] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-点化", ("weightEnlighten", "[Enlighten] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-净化", ("weightPurify", "[Purify] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-治愈", ("weightHeal", "[Heal] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-反重", ("weightAntiGravity", "[Anti-Gravity] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-传送", ("weightTeleport", "[Teleport] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-苏生", ("weightResurrect", "[Resurrect] weight for being randomly drawn. Set to 0 and this effect won't be drawn.") },
            { "法师|权重-血祭", ("weightBloodSacrifice", "[Blood Sacrifice] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-献祭", ("weightSacrifice", "[Sacrifice] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-易位", ("weightSwap", "[Swap] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-天灾", ("weightCalamity", "[Calamity] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-虫灾", ("weightInsectPlague", "[Insect Plague] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-尸变", ("weightZombify", "[Zombify] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-还魂", ("weightSoulReturn", "[Soul Return] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "法师|权重-反噬", ("weightBacklash", "[Backlash] weight for being randomly drawn (black magic pool only). Set to 0 and this effect won't be drawn.") },
            { "挑战者|启用职业", ("enabled", "Whether to enable the Challenger class.") },
            { "挑战者|最大人数", ("maxPlayers", "Maximum number of Challengers assigned in a match. 0 = unlimited. Default 1.") },
            { "挑战者|最小人数", ("minPlayers", "Minimum number of Challengers assigned in a match (used to fill first during random assignment). Default 0.") },
            { "挑战者|抽取权重", ("weight", "Weight for the Challenger to be drawn during random assignment. Default 10.") },
            { "挑战者|极限-初始诅咒", ("limitInitialCurse", "[Extreme] Curse automatically gained at the start (0.60 = 60 points). Default 0.60. Set to 0 to disable.") },
            { "挑战者|极限-初始石化", ("limitInitialPetrify", "[Extreme] Petrify automatically gained at the start (0.70 = 70 points). Default 0.70. Set to 0 to disable.") },
            { "挑战者|极限-复活诅咒", ("limitReviveCurse", "[Extreme] On revive after death, curse is restored to exactly this fixed value (0.60 = 60 points). Default 0.60. Vanilla revive adds +5 points of curse; the host realigns curse to this fixed value after revive (delta is sent). Set to 0 to zero out curse on revive.") },
            { "挑战者|极限-复活石化", ("limitRevivePetrify", "[Extreme] On revive after death, petrify is restored to exactly this fixed value (0.70 = 70 points). Default 0.70. Vanilla revive subtracts 75 points of petrify; the host repeatedly corrects it into place after revive (absolute assignment, idempotent). Set to 0 to stop restoring petrify on revive.") },
            { "挑战者|顶级玩家-黄金抓钩", ("topPlayerGoldenHook", "[Top Player] Number of golden hooks granted at the start (prefab RescueHook_Infinite, the infinite golden rescue claw of hook mode). Default 1. Set to 0 to not grant.") },
            { "挑战者|顶级玩家-滑翔翼", ("topPlayerGlider", "[Top Player] Number of gliders granted at the start (prefab Glider). Default 1. Set to 0 to not grant.") },
            { "挑战者|顶级玩家-免疫潘多拉", ("topPlayerPandoraImmune", "[Top Player] Whether the Challenger is immune to Pandora's class effect: standing within Pandora's range will not apply the Pandora's Box. Default true (refer to Saint's Detached, but only covers Pandora; does not resist undead aura injury / forced follow-dance of the crowd cheer).") },
            { "挑战者|不屑-损伤", ("disdainInjury", "[Disdain] Injury immediately added to self when hooking a player with a hook (golden hook / rescue hook) (0.50 = 50 points). Set to 0 to disable.") },
            { "挑战者|不屑-魔盒消失", ("disdainBoxVanish", "[Disdain] When the Challenger picks up the Pandora's Box (prefab PandorasBox), the item vanishes immediately and does not enter the backpack. Default true. Set to false to disable (then the box can be picked up normally).") },
            { "特级厨师|启用职业", ("enabled", "Whether to enable the MasterChef class.") },
            { "特级厨师|最大人数", ("maxPlayers", "Maximum number of MasterChefs assigned in a match. 0 = unlimited. Default 1.") },
            { "特级厨师|最小人数", ("minPlayers", "Minimum number of MasterChefs assigned in a match (used to fill first during random assignment). Default 0.") },
            { "特级厨师|抽取权重", ("weight", "Weight for the MasterChef to be drawn during random assignment. Default 10.") },
            { "特级厨师|自带厨具-初始数量", ("ownCookwareInitialCount", "[Own Cookware] Initial number of portable stoves granted at the start (prefab PortableStovetopItem). Placed into the 3 inventory slots first; if all are full, spawned at the player's feet. Default 1. Set to 0 to not grant.") },
            { "特级厨师|自带厨具-发放间隔", ("ownCookwareGrantInterval", "[Own Cookware] How many seconds between each extra portable stove granted (default 300 seconds = 5 minutes). Set to 0 or negative to disable.") },
            { "特级厨师|自带厨具-每次数量", ("ownCookwareCount", "[Own Cookware] Number of portable stoves granted per trigger. Default 1.") },
            { "特级厨师|手暖炉-间隔", ("handWarmerInterval", "[Hand Warmer] How many seconds between each settlement of the hot bonus for holding a portable stove (default 1 second). Set to 0 or negative to disable.") },
            { "特级厨师|手暖炉-炎热量", ("handWarmerHot", "[Hand Warmer] Hot gained per settlement (0.025 = 2.5 points). Default 0.025.") },
            { "特级厨师|烹饪-减饥饿", ("cookingHungerReduce", "[Cooking] Hunger reduced on self per item cooked in a match (0.025 = 2.5 points). Default 0.025. Set to 0 to disable.") },
            { "特级厨师|煤气中毒-每N次", ("gasPoisonEveryN", "[Gas Poisoning] Number of items cooked per poison trigger in a match. Default 3. Set to 0 to disable.") },
            { "特级厨师|煤气中毒-中毒量", ("gasPoisonAmount", "[Gas Poisoning] Poison added per trigger (0.10 = 10 points). Default 0.10.") },
            { "特级厨师|破坏大师-触发间隔", ("demolitionMasterInterval", "[Demolition Master] Within each interval of how many seconds, cooking non-food items grants extra stamina at most once (default 60 seconds = 1 minute). That is, multiple non-food cookings within the same minute trigger only once. Set to 0 or negative to disable.") },
            { "特级厨师|破坏大师-额外体力", ("demolitionMasterExtraStamina", "[Demolition Master] Extra stamina gained on trigger (0.10 = 10 points). Default 0.10.") },
            { "炊事员|启用职业", ("enabled", "Whether to enable the Cook class.") },
            { "炊事员|最大人数", ("maxPlayers", "Maximum number of Cooks assigned in a match. 0 = unlimited. Default 1.") },
            { "炊事员|最小人数", ("minPlayers", "Minimum number of Cooks assigned in a match (used to fill first during random assignment). Default 0.") },
            { "炊事员|抽取权重", ("weight", "Weight for the Cook to be drawn during random assignment. Default 10.") },
            { "炊事员|后勤保障-每层数量", ("logisticsPerLevelCount", "[Logistics Support] Number of portable stoves automatically gained on entering each new level (prefab PortableStovetopItem). Placed into the 3 inventory slots first; if all are full, spawned at the player's feet. Default 1. Set to 0 to not grant.") },
            { "炊事员|后勤保障-发放间隔", ("logisticsGrantInterval", "[Logistics Support] How many seconds between each extra portable stove granted (default 180 seconds = 3 minutes). Set to 0 or negative to disable.") },
            { "炊事员|后勤保障-每次数量", ("logisticsCount", "[Logistics Support] Number of portable stoves granted per trigger. Default 1.") },
            { "炊事员|后勤保障-后勤半径", ("logisticsRadius", "[Logistics Support] The random food grant below triggers only when a Logistician is within this many meters of self. Default 30.") },
            { "炊事员|后勤保障-食物间隔", ("logisticsFoodInterval", "[Logistics Support] When a Logistician is within radius, grant 1 random food into self's 3 inventory slots every this many seconds (default 90 seconds). Not granted when all 3 slots are full, and never forced into the main hand (same rule as Logistician's Emergency Airdrop). Set to 0 or negative to disable.") },
            { "炊事员|后勤保障-食物池", ("logisticsFoodPool", "[Logistics Support] Candidate pool of random food (item prefab names separated by English commas). Default 53 entries: 22 normal foods + all 19 berries + 12 mushrooms (including poisonous variants such as Mushroom Cluster Poison, Mushroom Lace Poison, Mushroom Normie Poison). Misspelled or unimplemented names are skipped automatically. When left empty, falls back to all items in the database that carry the restore-hunger component Action_RestoreHunger.") },
            { "炊事员|饮食供给-半径", ("foodSupplyRadius", "[Food Supply] Effect radius when cooking a never-cooked food (default 15 meters, including self).") },
            { "炊事员|饮食供给-减饥饿", ("foodSupplyHungerReduce", "[Food Supply] Hunger reduced for each player within radius (0.05 = 5 points). Default 0.05.") },
            { "炊事员|饮食供给-额外体力", ("foodSupplyExtraStamina", "[Food Supply] Extra stamina gained by each player within radius (0.05 = 5 points). Default 0.05.") },
            { "炊事员|食品安全-减饥饿", ("foodSafetyHungerReduce", "[Food Safety] Hunger reduced on self after eating cooked food (0.025 = 2.5 points). Default 0.025.") },
            { "炊事员|食品安全-减损伤", ("foodSafetyInjuryReduce", "[Food Safety] Injury reduced on self after eating cooked food (0.025 = 2.5 points). Default 0.025.") },
            { "炊事员|食品安全-额外体力", ("foodSafetyExtraStamina", "[Food Safety] Extra stamina gained on self after eating cooked food (0.10 = 10 points). Default 0.10.") },
            { "炊事员|创伤应激-损伤", ("traumaInjury", "[Trauma Stress] Injury added on self after eating uncooked food (0.10 = 10 points). Default 0.10. (Except Mushroom Glow, Energy Drink, FortifiedMilk, Lollipop)") },
            { "炊事员|创伤应激-中毒", ("traumaPoison", "[Trauma Stress] Poison added on self after eating uncooked food (0.20 = 20 points). Default 0.20.") },
            { "炊事员|创伤应激-困倦", ("traumaDrowsy", "[Trauma Stress] Drowsy added on self after eating uncooked food (0.30 = 30 points). Default 0.30.") },
            { "炊事员|创伤应激-光环半径", ("traumaAuraRadius", "[Trauma Stress] Radius of continuous detection (default 15 meters).") },
            { "炊事员|创伤应激-间隔", ("traumaInterval", "[Trauma Stress] When a player (including self) within radius has hunger above the threshold, add drowsy to self every this many seconds (default 3 seconds). Set to 0 or negative to disable.") },
            { "炊事员|创伤应激-饥饿阈值", ("traumaHungerThreshold", "[Trauma Stress] Hunger threshold for detection (0.30 = 30 points). Triggers when a player within radius has hunger above this value. Default 0.30.") },
            { "炊事员|创伤应激-困倦量", ("traumaDrowsyAmount", "[Trauma Stress] Drowsy added to self per trigger (0.05 = 5 points). Default 0.05.") },
            { "炊事员|创伤应激-黑名单", ("traumaBlacklist", "[Trauma Stress] Eating these items does NOT trigger injury / poison / drowsy (prefab names, separated by English commas). Default: Mushroom Glow (class-change trigger item), Energy Drink, FortifiedMilk, Lollipop. Empty means no blacklist.") },
            { "和平主义者|启用职业", ("enabled", "Whether to enable the Pacifist class.") },
            { "和平主义者|最大人数", ("maxPlayers", "Maximum number of Pacifists assigned in a match. 0 = unlimited. Default 1.") },
            { "和平主义者|最小人数", ("minPlayers", "Minimum number of Pacifists assigned in a match (used to fill first during random assignment). Default 0.") },
            { "和平主义者|抽取权重", ("weight", "Weight for the Pacifist to be drawn during random assignment. Default 10.") },
            { "和平主义者|和平？-初始诅咒", ("peaceInitialCurse", "[Peace?] Curse automatically gained at the start (0.20 = 20 points). Default 0.20. Set to 0 to disable.") },
            { "和平主义者|和平？-踢中体力", ("peaceKickExtraStamina", "[Peace?] Extra stamina gained when kicking a player (0.025 = 2.5 points). Default 0.025.") },
            { "和平主义者|和平？-未中扣体力", ("peaceMissDeductStamina", "[Peace?] Extra stamina deducted when a kick misses a player (0.025 = 2.5 points). Default 0.025.") },
            { "和平主义者|和平？-未中困倦", ("peaceMissDrowsy", "[Peace?] Drowsy added when a kick misses a player (0.20 = 20 points). Default 0.20.") },
            { "和平主义者|和平？-踢人冷却", ("peaceKickCooldown", "[Peace?] Minimum interval (seconds) between two right-click kicks, used for deduplication: after holding right-click, vanilla repeatedly broadcasts start-pulling within about 0.2 seconds, and without throttling a single key press kicks several times. Default 0.7.") },
            { "和平主义者|和平？-踢人距离", ("peaceKickRange", "[Peace?] Judgement distance of the kick (meters): only players within this distance and inside the forward cone count as a hit. Default 1.5 (vanilla kick judgement distance is about 1 meter).") },
            { "和平主义者|和平？-踢人角度", ("peaceKickAngle", "[Peace?] Judgement angle of the kick (degrees, one side): if the angle between the target and the kicker's facing exceeds this value, it is not a hit. Default 60 (vanilla kick is about 45).") },
            { "和平主义者|和平？-击倒时长", ("peaceKnockdownDuration", "[Peace?] Duration (seconds) for a kicked player to enter the downed (ragdoll) state, matching the vanilla kick knockdown duration. Default 1. Set to 0 to only settle stamina and sound without knocking the target down.") },
            { "仓鼠|启用职业", ("enabled", "Whether to enable the Hamster class.") },
            { "仓鼠|最大人数", ("maxPlayers", "Maximum number of Hamsters assigned in a match. 0 = unlimited. Default 1.") },
            { "仓鼠|最小人数", ("minPlayers", "Minimum number of Hamsters assigned in a match (used to fill first during random assignment). Default 0.") },
            { "仓鼠|抽取权重", ("weight", "Weight for the Hamster to be drawn during random assignment. Default 10.") },
            { "仓鼠|我全都要-初始背包", ("wantAllInitialBackpack", "[I Want It All] Number of backpacks equipped for the Hamster at the start. Default 1 (one empty backpack). Same mechanism as the Logistician's Well Prepared: granted idempotently every frame after class assignment; an already-equipped backpack is overwritten. Set to 0 to disable.") },
            { "仓鼠|我全都要-负重阈值", ("wantAllWeightThreshold", "[I Want It All] Minimum self weight required to trigger speed-up (0.50 = 50 points). Weight is computed live by vanilla from backpack + 3 inventory slots + main hand + carried teammate, and written into the state array (index Weight) in quantum steps of 0.025; this mod reads that synced value directly. Default 0.50.") },
            { "仓鼠|我全都要-加速间隔", ("wantAllSpeedInterval", "[I Want It All] Maintains speed-up while weight meets the threshold: re-granted immediately once the effect ends (achieving infinite speed-up); this value is the minimum interval (seconds) between two re-grants. Default 10. Note: the vanilla Energy Drink's speed-up (FasterBoi) does not extend duration when drunk again while active (Affliction_FasterBoi.Stack only takes max(totalTime) and does not reset accumulated timeElapsed), so blind granting at a fixed interval cannot chain it; this mod instead re-grants as soon as the effect ends. This value must be less than the measured duration of the Energy Drink (about 11 seconds) to guarantee no gap. Set to 0 or negative to disable this effect.") },
            { "仓鼠|我全都要-加速清除困倦", ("wantAllSpeedClearDrowsy", "[I Want It All] After the Energy Drink's speed-up ends and the player is given drowsy, the amount of drowsy cancelled by the host (0.25 = 25 points). Same principle as Explorer's High Metabolism - clear drowsy after speed-up. Set to 0 to disable clearing.") },
            { "仓鼠|我全都要-额外体力间隔", ("wantAllExtraStaminaInterval", "[I Want It All] While weight meets the threshold, gain extra stamina every this many seconds (seconds). Default 20. Timed independently from I Want It All - speed interval. Set to 0 or negative to disable.") },
            { "仓鼠|我全都要-额外体力", ("wantAllExtraStamina", "[I Want It All] Extra stamina gained each time while weight meets the threshold (0.05 = 5 points). Default 0.05. Set to 0 to disable.") },
            { "救火队员|启用职业", ("enabled", "Whether to enable the Firefighter class.") },
            { "救火队员|最大人数", ("maxPlayers", "Maximum number of Firefighters assigned in a match. 0 = unlimited. Default 1.") },
            { "救火队员|最小人数", ("minPlayers", "Minimum number of Firefighters assigned in a match (used to fill first during random assignment). Default 0.") },
            { "救火队员|抽取权重", ("weight", "Weight for the Firefighter to be drawn during random assignment. Default 10.") },
            { "救火队员|温暖臂膀-间隔", ("warmArmInterval", "[Warm Arms] When carrying a player, how many seconds between each healing settlement (seconds). Default 20. Set to 0 or negative to disable.") },
            { "救火队员|温暖臂膀-减损伤", ("warmArmInjuryReduce", "[Warm Arms] Injury reduced per settlement for both the Firefighter and the player he is carrying (0.025 = 2.5 points). Default 0.025. Only settles while the Firefighter is carrying someone: the carried unconscious teammate is the very purpose of carrying, so they receive healing too.") },
            { "救火队员|火线救援-无敌物品", ("frontlineRescueInvincibleItem", "[Frontline Rescue] Prefab name of the invincibility item granted to the Firefighter each time a player enters unconscious (downed, not dead). Default FortifiedMilk = milk gold (vanilla invincibility effect). Placed into an empty inventory slot first; if all 3 slots are full, spawned at the player's feet.") },
            { "救火队员|火线救援-加速清除困倦", ("frontlineRescueSpeedClearDrowsy", "[Frontline Rescue] After the Energy Drink's speed-up ends and the player is given drowsy, the amount of drowsy cancelled by the host (0.25 = 25 points). Same principle as Explorer's High Metabolism - clear drowsy after speed-up. Set to 0 to disable clearing.") },
            { "救火队员|火线救援-延迟", ("frontlineRescueDelay", "[Frontline Rescue] After a player enters unconscious, how many seconds the Firefighter delays before going to rescue (seconds). Default 3. When the time is up, if that unconscious player is still unconscious and the Firefighter is still alive, an invincibility effect is applied to them and the Firefighter is teleported to that unconscious player, waiting to carry them.") },
            { "救火队员|火线救援-额外体力", ("frontlineRescueExtraStamina", "[Frontline Rescue] Extra stamina gained at once when the Firefighter picks up the unconscious player waiting for rescue (0.50 = 50 points). Default 0.50. Set to 0 to disable.") },
            { "救火队员|火线救援-冷却", ("frontlineRescueCooldown", "[Frontline Rescue] Minimum interval (seconds) between two triggers for each Firefighter. Default 10. Registering a rescue task for the Firefighter when a player enters unconscious counts as one trigger; no new rescue tasks are registered during cooldown. Also: this effect cannot trigger while the Firefighter is himself carrying a player. Set to 0 or negative to disable cooldown.") },
            { "救火队员|尽职尽责-石化", ("dedicatedPetrify", "[Dedicated] Each time a human player dies (actually dies; unconscious does not count; skeleton players do not count), the petrify added to each Firefighter (0.15 = 15 points). Default 0.15. Set to 0 to disable.") },
            { "救火队员|尽职尽责-冷却", ("dedicatedCooldown", "[Dedicated] Minimum interval (seconds) between two petrify for each Firefighter. Default 60. Still triggered by every human player death, but each Firefighter settles at most once per cooldown. Set to 0 or negative to disable cooldown.") },
            { "自恋狂|启用职业", ("enabled", "Whether to enable the Narcissist class.") },
            { "自恋狂|最大人数", ("maxPlayers", "Maximum number of Narcissists assigned in a match. 0 = unlimited. Default 1.") },
            { "自恋狂|最小人数", ("minPlayers", "Minimum number of Narcissists assigned in a match (used to fill first during random assignment). Default 0.") },
            { "自恋狂|抽取权重", ("weight", "Weight for the Narcissist to be drawn during random assignment. Default 10.") },
            { "自恋狂|化妆盒-每层数量", ("makeupBoxPerLevelCount", "[Makeup Box] Number of sunscreen sprays automatically gained on entering each new level (default 3). Force-overwrites the player's 3 inventory slots (clears the target slot first, then writes, so it is granted even if the inventory is full). Set to 0 to disable.") },
            { "自恋狂|化妆盒-物品", ("makeupBoxItem", "[Makeup Box] Prefab name of the item granted. Default Sunscreen = sunscreen spray.") },
            { "自恋狂|精致-初始诅咒", ("exquisiteInitialCurse", "[Exquisite] Initial curse carried at the start (0.10 = 10 points). Default 0.10. Set to 0 to disable. Same mechanism as the Leader's Fate and other initial curses (absolute assignment + repeated correction); late joiners are topped up idempotently after reviving into place.") },
            { "自恋狂|精致-额外体力", ("exquisiteExtraStamina", "[Exquisite] Extra stamina gained each time 1 sunscreen spray is used up (0.30 = 30 points). Default 0.30.") },
            { "自恋狂|精致-状态额外体力", ("exquisiteStatusExtraStamina", "[Exquisite] Extra stamina gained each time self gains the sunscreen status (applying the vanilla Sunscreen status via sunscreen spray, including refreshes) (0.20 = 20 points). Default 0.20. Set to 0 to disable.") },
            { "自恋狂|精致-状态额外体力冷却", ("exquisiteStatusExtraStaminaCooldown", "[Exquisite] Cooldown (seconds) for gaining extra stamina each time the sunscreen status is gained. Default 5. The sunscreen status is refreshed repeatedly while it lasts (every refresh triggers a gain), so to prevent high-frequency extra stamina farming, the same player settles only once per cooldown. Set to 0 or negative to disable cooldown (no rate limit).") },
            { "自恋狂|化学中毒-石化", ("chemicalPoisonPetrify", "[Chemical Poisoning] Petrify added each time 1 sunscreen spray is used up (0.10 = 10 points). Default 0.10. Set to 0 to disable.") },
            { "独狼|启用职业", ("enabled", "Whether to enable the Lone Wolf class.") },
            { "独狼|最大人数", ("maxPlayers", "Maximum number of Lone Wolves assigned in a match. 0 = unlimited. Default 1.") },
            { "独狼|最小人数", ("minPlayers", "Minimum number of Lone Wolves assigned in a match (used to fill first during random assignment). Default 0.") },
            { "独狼|抽取权重", ("weight", "Weight for the Lone Wolf to be drawn during random assignment. Default 10.") },
            { "独狼|独行-间隔", ("soloInterval", "[Lone Road] When there is no other player nearby (no other living player within self's solo radius), gain extra stamina every this many seconds (seconds). Default 30. Set to 0 to disable.") },
            { "独狼|独行-半径", ("soloRadius", "[Lone Road] Distance (meters) for judging no one nearby, centered on the Lone Wolf; being alone means no other player within this radius. Default 50.") },
            { "独狼|独行-额外体力", ("soloExtraStamina", "[Lone Road] Extra stamina gained per solo settlement (0.10 = 10 points). Default 0.10. Set to 0 to disable.") },
            { "独狼|同伴-半径", ("companionRadius", "[Lone Road] Distance (meters) for judging someone nearby, centered on the Lone Wolf; any other player within this radius triggers drowsy. Default 15.") },
            { "独狼|同伴-困倦间隔", ("companionDrowsyInterval", "[Lone Road] When a player is nearby, apply drowsy every this many seconds (seconds). Default 3. Set to 0 to disable.") },
            { "独狼|同伴-困倦", ("companionDrowsy", "[Lone Road] Drowsy applied each time when a player is nearby (0.025 = 2.5 points). Default 0.025. Set to 0 to disable.") },
            { "炮手|启用职业", ("enabled", "Whether to enable the Gunner class.") },
            { "炮手|最大人数", ("maxPlayers", "Maximum number of Gunners assigned in a match. 0 = unlimited. Default 1.") },
            { "炮手|最小人数", ("minPlayers", "Minimum number of Gunners assigned in a match (used to fill first during random assignment). Default 0.") },
            { "炮手|抽取权重", ("weight", "Weight for the Gunner to be drawn during random assignment. Default 10.") },
            { "炮手|开炮-每层大炮数", ("fireCannonPerLevelCount", "[Fire Cannon] Number of ScoutCannonItem automatically gained on entering each new level (default 1). Placed into an empty inventory slot first; if no slot is free, it is not granted this time and retried in later frames. Set to 0 to disable.") },
            { "炮手|开炮-大炮间隔", ("fireCannonInterval", "[Fire Cannon] Gain one extra ScoutCannonItem every this many seconds (seconds). Default 180 (3 minutes). Set to 0 to disable.") },
            { "炮手|开炮-大炮数", ("fireCannonCount", "[Fire Cannon] Number of ScoutCannonItem gained at each cannon interval (default 1).") },
            { "炮手|炸膛-炸药", ("barrelBurstDynamite", "[Barrel Burst] Number of Dynamite gained each time self takes injury (injury status increased versus the previous round) (default 1). Placed into an empty inventory slot first; if all 3 slots are full, placed into the main hand and forced to be held. Set to 0 to disable.") },
            { "乐队成员|启用职业", ("enabled", "Whether to enable the Band class.") },
