            { "乐队成员|抽取权重", ("weight", "Weight of the Band class when randomly assigning. Default 5.") },
            { "乐队成员|乐器-不变权重", ("instrumentKeepWeight", "[Instrument] Weight of keeping the item unchanged when picking up an item (default 50).") },
            { "乐队成员|乐器-小号权重", ("instrumentBugleWeight", "[Instrument] Weight of turning a picked-up item into a Bugle (default 30).") },
            { "乐队成员|乐器-号角权重", ("instrumentHornWeight", "[Instrument] Weight of turning a picked-up item into the Scoutmaster's Bugle (Bugle_Scoutmaster Variant) (default 10).") },
            { "乐队成员|乐器-友谊喇叭权重", ("instrumentFriendshipHornWeight", "[Instrument] Weight of turning a picked-up item into the Friendship Horn (Bugle_Magic) (default 10).") },
            { "乐队成员|乐器-黑名单", ("instrumentBlacklist", "[Instrument] Pickup replacement blacklist (comma-separated prefab names): matching items are never replaced with an instrument. By default excludes Mushroom Glow, the three instruments themselves, the Flare, and the 5 Scout amulets.") },
            { "乐队成员|乐器-检测间隔", ("instrumentCheckInterval", "[Instrument] How often (in seconds) the instruments carried in the 3 inventory slots are scanned. Default 30. Set to 0 to disable.") },
            { "乐队成员|乐器-小号额外体力", ("instrumentBugleExtraStamina", "[Instrument] Extra stamina added for each Bugle carried when detected (0.025 = 2.5 points). Default 0.025.") },
            { "乐队成员|乐器-号角额外体力", ("instrumentHornExtraStamina", "[Instrument] Extra stamina added for each Scoutmaster's Bugle (Bugle_Scoutmaster Variant) carried when detected (0.05 = 5 points). Default 0.05.") },
            { "乐队成员|乐器-友谊喇叭额外体力", ("instrumentFriendshipHornExtraStamina", "[Instrument] Extra stamina added for each Friendship Horn (Bugle_Magic) carried when detected (0.05 = 5 points). Default 0.05.") },
            { "乐队成员|演奏-单次半径", ("performanceSingleRadius", "[Performance] Effect radius (in meters, excluding self) per single blow. Default 15.") },
            { "乐队成员|演奏-单次额外体力", ("performanceSingleExtraStamina", "[Performance] Extra stamina granted to other players within the radius per blow (0.025 = 2.5 points). Default 0.025. Set to 0 to disable.") },
            { "乐队成员|演奏-冷却", ("performanceCooldown", "[Performance] Cooldown / deduplication window (in seconds) for the Bugle's single-blow effect. Default 1. Set to 0 to disable deduplication.") },
            { "乐队成员|演奏-号角自身额外体力", ("performanceHornSelfExtraStamina", "[Performance] Extra stamina added to self when blowing the Scoutmaster's Bugle (Bugle_Scoutmaster Variant) (0.025 = 2.5 points). Default 0.025. Set to 0 to disable.") },
            { "乐队成员|演奏-困倦每当吹响次数", ("performanceDrowsyEveryCount", "[Performance] After how many cumulative blows (Bugle / Horn / Friendship Horn combined) drowsy is applied to self once. Default 4. Set to 0 to disable.") },
            { "乐队成员|演奏-困倦量", ("performanceDrowsyAmount", "[Performance] Drowsy added to self for every performanceDrowsyEveryCount cumulative blows (0.05 = 5 points). Default 0.05.") },
            { "乐队成员|乐队-间隔", ("bandIntervalSeconds", "[Band] How often (in seconds) the effect is settled based on the number of nearby other Band members. Default 30. Set to 0 to disable.") },
            { "乐队成员|乐队-半径", ("bandRadius", "[Band] Distance (in meters) used to scan for nearby other Band members. Default 15.") },
            { "乐队成员|乐队-额外体力", ("bandExtraStamina", "[Band] Extra stamina added per nearby other Band member (0.05 = 5 points). Default 0.05.") },
            { "乐队成员|乐队-清除困倦", ("bandClearDrowsy", "[Band] Drowsy cleared per nearby other Band member (0.30 = 30 points). Default 0.30.") },
            { "乐队成员|乐队-半径加成", ("bandRadiusBonus", "[Band] Meters added to the [Performance] radius per nearby other Band member. Default 5.") },
            { "乐队成员|乐队-半径加成上限", ("bandRadiusBonusCap", "[Band] Cap (in meters) on the [Performance] radius bonus. Default 20.") },
            { "乐队成员|转职-启用", ("transferEnabled", "Whether to enable the [Band] supplementary effect: players who carry an instrument near a Band member for a long time may convert to the Band class.") },
            { "乐队成员|转职-物品", ("transferItems", "[Band] Instrument prefab names (comma-separated) required to trigger the conversion check: the condition is met when at least 1 of the player's 3 inventory slots holds any of them. Default Bugle, the Scoutmaster's Bugle (Bugle_Scoutmaster Variant), the Friendship Horn (Bugle_Magic).") },
            { "乐队成员|转职-半径", ("transferRadius", "[Band] Distance (in meters) used to determine that a Band member is nearby. Default 5.") },
            { "乐队成员|转职-检测间隔", ("transferCheckInterval", "[Band] Check interval (in seconds) for the supplementary effect. Default 30. Set to 0 to disable this effect.") },
            { "乐队成员|转职-连续次数", ("transferStreakCount", "[Band] Number of consecutive successful checks required before entering the chance-based conversion check. Default 2 (i.e. about 2 x transferCheckInterval seconds of consecutive success); no check is performed while the condition is not continuously met, to save performance.") },
            { "乐队成员|转职-概率", ("transferChance", "[Band] Chance (0.10 = 10%) of immediately converting to a Band member, checked once per transferCheckInterval seconds after the condition is met. Default 0.10. This conversion is triggered by the passive effect, costs nothing, is not limited by the conversion count, and bypasses the maxPlayers limit.") },
            { "乐队成员|体弱-初始诅咒", ("frailtyInitialCurse", "[Frailty] Initial curse value at the start of the run (0.20 = 20 points). Default 0.20. Set to 0 to disable. Uses the same mechanism as the Leader's Fate and other initial curses (absolute assignment + repeated correction); late joiners are idempotently topped up after they revive in place.") },
            { "残魂|启用职业", ("enabled", "Whether to enable the Lead Miles Soul class.") },
            { "残魂|最大人数", ("maxPlayers", "Maximum number of Miles Souls assigned this run. 0 = unlimited. Default 1.") },
            { "残魂|最小人数", ("minPlayers", "Minimum number of Miles Souls assigned this run (used to prioritize filling when randomly assigning). Default 0.") },
            { "残魂|抽取权重", ("weight", "Weight of the Miles Soul when randomly assigning. Default 10.") },
            { "残魂|受诅残魂-初始诅咒", ("cursedSoulInitialCurse", "[Cursed Soul] Initial curse value at the start of the run (0.15 = 15 points). Default 0.15. Set to 0 to disable. Uses the same mechanism as the Leader's Fate and other initial curses (absolute assignment + repeated correction); late joiners are idempotently topped up after they revive in place.") },
            { "残魂|受诅残魂-保护启用", ("cursedSoulProtectionEnabled", "[Cursed Soul] Whether curse protection is enabled: other than own class effects and Mage - Magic Scroll - Purify, any reduction of own curse by any means is forcibly restored to the latest recorded value. Default true.") },
            { "残魂|受诅残魂-检测间隔", ("cursedSoulCheckInterval", "[Cursed Soul] How often (in seconds) it checks whether own curse has been externally reduced. Default 1.") },
            { "残魂|受诅残魂-免疫潘多拉", ("cursedSoulImmunePandora", "[Cursed Soul] Whether immune to Pandora's Child's [Pandora] effect (Pandora's box is not applied). Default true. Shares the Pandora entry guard with the Saint's [Transcendence].") },
            { "残魂|受诅残魂-仅海滩可成为", ("cursedSoulShoreOnly", "[Cursed Soul] Whether to restrict this class to only being obtainable on the first-level beach (Shore biome): after lighting the beach campfire and entering level 2 (Rainforest / jungle mushroom etc.), new late-joining players and class conversions of players present can no longer become a Miles Soul (already assigned souls are unaffected; only new ones are blocked). Default true.") },
            { "残魂|众魂阻挠-每层诅咒", ("soulHindrancePerLevelCurse", "[Soul Hindrance] Curse added to self each time a new level is entered (0.05 = 5 points). Default 0.05. Not added when entering the Peak biome or the Void biome.") },
            { "残魂|众魂阻挠-触发次数", ("soulHindranceTriggerCount", "[Soul Hindrance] After how many cumulative uses of Scout gem items (Perseverance / Initiative / Hospitality / Ambition combined), 1 Scoutmaster is spawned outside own radius. Default 13. Set to 0 to disable.") },
            { "残魂|众魂阻挠-生成距离", ("soulHindranceSpawnDistance", "[Soul Hindrance] Scoutmaster spawn distance: spawned beyond this distance from self in a random direction (meters). Default 30.") },
            { "残魂|众魂阻挠-追击时间", ("soulHindranceChaseDuration", "[Soul Hindrance] Duration (in seconds) the Scoutmaster is forced to chase after spawning; after this it reverts to vanilla AI. Default 30.") },
            { "残魂|封印之力-启用", ("sealPowerEnabled", "[Seal Power] Master switch. When on, any item except special items vanishes immediately when picked up. Default true.") },
            { "残魂|封印之力-特殊物品", ("sealPowerSpecialItems", "[Seal Power] Special item whitelist (comma-separated prefab names): these items can still be picked up normally. Default = Mushroom Glow, Flare, the Scout's Perseverance / Initiative / Hospitality / Ambition / Honor, Strange Gem, Backpack, Funny Backpack.") },
            { "残魂|封印之力-客机判定阈值", ("sealPowerClientDetectThreshold", "[Seal Power] Petrify-value threshold (points) for detecting a client player using a Scout gem item. Reason: direct use of a Scout gem is a local action on the user's client and does not broadcast an RPC, so the host cannot detect it directly. Therefore a heuristic is used for clients: when a player is holding a Scout gem item (CharacterData.currentItem) and their petrify value increases by >= this threshold at once, it counts as using that gem once. Default 2.5: touching the Furnace / Bog special stones adds exactly +2.5 each time (no trigger), while each gem use adds more than 2.5 petrify (trigger). Set to 0 or negative to disable this client detection channel (client gem use will then not be detected).") },
            { "残魂|封印之力-客机判定间隔", ("sealPowerClientDetectInterval", "[Seal Power] Polling interval (in seconds) for the client holding-a-gem + petrify-increase heuristic. Default 0.5.") },
            { "残魂|封印之力-客机判定冷却", ("sealPowerClientDetectCooldown", "[Seal Power] Cooldown (in seconds) after a client heuristic check hits: the same gem of the same player is not counted again within this cooldown, preventing continuously-increasing-petrify gems from being triggered repeatedly. The cooldown is timed per player + gem; switching to another gem is unaffected. Default 1.") },
            { "残魂|毅力-石化", ("perseverancePetrify", "[Perseverance] Petrify immediately reduced after each use of the Scout's Perseverance (Amulet_Healing) (0.10 = 10 points). Default 0.10.") },
            { "残魂|毅力-饥饿", ("perseveranceHunger", "[Perseverance] Hunger immediately reduced after each use (0.10 = 10 points). Default 0.10.") },
            { "残魂|毅力-首拾诅咒", ("perseveranceFirstPickupCurse", "[Perseverance] Curse reduced on the first pickup this run (0.05 = 5 points). Default 0.05.") },
            { "残魂|进取-石化", ("initiativePetrify", "[Initiative] Petrify immediately reduced after each use of the Scout's Initiative (Amulet_SuperJump) (0.05 = 5 points). Default 0.05.") },
            { "残魂|进取-饥饿", ("initiativeHunger", "[Initiative] Hunger immediately reduced after each use (0.05 = 5 points). Default 0.05.") },
            { "残魂|进取-额外体力", ("initiativeExtraStamina", "[Initiative] Extra stamina immediately added after each use (0.05 = 5 points). Default 0.05. Set to 0 to disable.") },
            { "残魂|进取-首拾诅咒", ("initiativeFirstPickupCurse", "[Initiative] Curse reduced on the first pickup this run (0.05 = 5 points). Default 0.05.") },
            { "残魂|盛情-石化", ("hospitalityPetrify", "[Hospitality] Petrify immediately reduced after each use that successfully copied an item (Scout's Hospitality Amulet_Clone) (0.20 = 20 points). Default 0.20.") },
            { "残魂|盛情-饥饿", ("hospitalityHunger", "[Hospitality] Hunger immediately reduced after each use that successfully copied an item (0.10 = 10 points). Default 0.10.") },
            { "残魂|盛情-额外体力", ("hospitalityExtraStamina", "[Hospitality] Extra stamina immediately added after each use that successfully copied an item (0.20 = 20 points). Default 0.20. Set to 0 to disable.") },
            { "残魂|盛情-首拾诅咒", ("hospitalityFirstPickupCurse", "[Hospitality] Curse reduced on the first pickup this run (0.05 = 5 points). Default 0.05.") },
            { "残魂|野心-石化", ("ambitionPetrify", "[Ambition] Petrify immediately reduced after each use of the Scout's Ambition (Amulet_InfiniteStamina) (0.25 = 25 points). Default 0.25.") },
            { "残魂|野心-饥饿", ("ambitionHunger", "[Ambition] Hunger immediately reduced after each use (0.10 = 10 points). Default 0.10.") },
            { "残魂|野心-额外体力", ("ambitionExtraStamina", "[Ambition] Extra stamina immediately added after each use (0.25 = 25 points). Default 0.25.") },
            { "残魂|野心-首拾诅咒", ("ambitionFirstPickupCurse", "[Ambition] Curse reduced on the first pickup this run (0.05 = 5 points). Default 0.05.") },
            { "残魂|童军力量-诅咒", ("scoutPowerCurse", "[Scout Power] Curse additionally reduced after all four Scout gem items have been picked up (0.05 = 5 points), and all negative statuses other than curse (including petrify) are cleared. Default 0.05.") },
            { "残魂|零号守则-毅力助人", ("ruleZeroPerseveranceHelp", "[Rule Zero] When feeding the Scout's Perseverance to another player who is unconscious (downed but not dead): the petrify added to self by this use is cleared by an equal amount (net change of 0), and this use does not count toward the [Soul Hindrance] counter. Note the three cases (only Perseverance distinguishes them): self-use = Seal Power (-10 petrify / -10 hunger); feeding a non-unconscious other player = no class effect (vanilla petrify gain applies and it still counts); feeding an unconscious player = this entry. Default true.") },
            { "残魂|零号守则-额外体力", ("ruleZeroExtraStamina", "[Rule Zero] Extra stamina added to self when feeding Perseverance to an unconscious (downed but not dead) player, in addition to clearing the petrify added this time by an equal amount (0.30 = 30 points). Default 0.30. Set to 0 to disable.") },
            { "残魂|零号守则-无敌物品", ("ruleZeroInvincibleItem", "[Rule Zero] Invincibility-effect item applied to self when someone becomes unconscious (default FortifiedMilk). Leave empty to apply no invincibility effect (teleport only).") },
            { "残魂|零号守则-传送冷却", ("ruleZeroTeleportCooldown", "[Rule Zero] Trigger cooldown (in seconds) for unconscious -> invincibility + teleport to the unconscious player. Default 10. Set to 0 to disable the cooldown.") },
            { "残魂|零号守则-死亡损伤", ("ruleZeroDeathInjury", "[Rule Zero] Injury added to self for each player who dies (0.10 = 10 points). Default 0.10.") },
            { "残魂|零号守则-附近玩家-间隔", ("ruleZeroNearbyPlayersInterval", "[Rule Zero] How often (in seconds) the number of players within the radius around self is checked. Default 30. Set to 0 to disable.") },
            { "残魂|零号守则-附近玩家-半径", ("ruleZeroNearbyPlayersRadius", "[Rule Zero] Radius (in meters) of the above check. Default 30.") },
            { "残魂|零号守则-附近玩家-额外体力", ("ruleZeroNearbyPlayersExtraStamina", "[Rule Zero] Extra stamina added to self for each player within the check radius (excluding self) (0.05 = 5 points). Default 0.05. Example: 4 players within the radius -> +0.20 (20 points) at once.") },
            { "残魂|封印解放-启用", ("sealReleaseEnabled", "[Seal Release] Whether enabled: after releasing the Scoutmaster's soul at the Void, clears all negative statuses of all players present (including curse and petrify) and adds extra stamina. Default true.") },
            { "残魂|封印解放-额外体力", ("sealReleaseExtraStamina", "[Seal Release] Extra stamina granted to each player present on release (1 = 100 points). Default 1.") },
            { "区|启用职业", ("enabled", "Whether to enable the Qu class.") },
            { "区|最大人数", ("maxPlayers", "Maximum number of Qu assigned this run. 0 = unlimited. Default 4. [Many Qu] applies bonuses based on the number of living Qu within own radius (see manyQuThresholdRadius), including self (>=3 / >=4), and [Blockchain] forcibly converts players with excess spores into Qu, which requires several Qu to be near each other, so the default is 4.") },
            { "区|最小人数", ("minPlayers", "Minimum number of Qu assigned this run (used to prioritize filling when randomly assigning). Default 0.") },
            { "区|抽取权重", ("weight", "Weight of the Qu class when randomly assigning. Default 10.") },
            { "区|攀爬-启用", ("climbEnabled", "[!? Qu Qu?!] Whether to enable the climbing-is-always-slippery-as-in-rainforest-rain effect. Default true. In vanilla, climb speed and climb stamina cost multiplier are both resolved on the climber's own client (data.climbMod is not network-synced and is overwritten every frame by the owner from a local raycast), so the host cannot override them -> slower speed was abandoned. It is now implemented as periodic forced release (see the next two entries), which equivalently increases stamina cost by forcing the player to re-grip the wall and climb the same height again.") },
            { "区|攀爬-间隔", ("climbIntervalSeconds", "[!? Qu Qu?!] During climbing, how often (in seconds) the climb is forcibly interrupted. Default 0.5. Set to 0 or negative to disable. After the interruption the character releases (falls / must re-grip to resume climbing), equivalently consuming extra stamina. The timer only accumulates while climbing: once interrupted (isClimbing becomes false) it resets, so it does not run idle after release, and only triggers again after the player re-grips and climbs the full interval again.") },
            { "区|攀爬-忽略攀爬物", ("climbIgnoreClimbables", "[!? Qu Qu?!] While climbing, whether using placed/mounted climbables (vines / ropes / anti-gravity ropes / chains / pitons) does not trigger the forced release. Default true. true = only natural rock walls (vanilla isClimbing) are slippery and release; using the above climbables (ropes / anti-gravity ropes / chains -> isRopeClimbing; vines -> isVineClimbing; pitons hammered in that become climbing spikes / pickaxe -> hanging on ClimbHandle) does not release. false = any climbing (natural rock / rope / vine) releases.") },
            { "区|死亡生成虫儿-启用", ("deathSpawnBugEnabled", "[!? Qu Qu?!] When a Qu truly dies, whether a cooked Early Worm is spawned at the corpse. Default true.") },
            { "区|分解者-启用", ("decomposerEnabled", "[Decomposer] Whether enabled: picking up an item from the item pool below makes the item vanish and lowers own hunger. Default true.") },
            { "区|分解者-饥饿", ("decomposerHunger", "[Decomposer] Hunger reduced from self each time it triggers (0.05 = 5 points, applied as a negative). Default 0.05.") },
            { "区|分解者-物品池", ("decomposerItemPool", "[Decomposer] List of items that are decomposed immediately on pickup (comma-separated prefab names). Default = the four banana peels, Wood Stick, Torch, the three poisonous mushrooms (the poisonous variants of the Trumpet Mushroom / Silver Needle Mushroom / Bun Mushroom), Bounce Shroom, Trampoline Shroom, Cloud Shroom, Curvy Shroom, Elixir Shroom, Cactus, Magic Bean, Guidebook, Scroll, Book of Bones. Warning: torn-off book pages (including the pages generated by using a scroll) do not need to be listed here: their prefab names all start with GuidebookPage (observed as GuidebookPage_0_Intro / GuidebookPage_3_Revival / GuidebookPage_10_Sleepy / GuidebookPage_7_BurningSun ..., numbering and names change between versions), and the code matches them uniformly by that prefix, so GuidebookPage / GuidebookPageScroll Variant in this list are for documentation only. Names that are wrong or not implemented are skipped automatically.") },
            { "区|区块链-启用", ("blockchainEnabled", "[Blockchain] Whether enabled. Default true.") },
            { "区|区块链-间隔", ("blockchainIntervalSeconds", "[Blockchain] How often (in seconds) the settlement of clear own spores + add spores to nearby other players + infection check happens. Default 7.") },
            { "区|区块链-自身清除孢子", ("blockchainSelfClearSpores", "[Blockchain] Amount of spores cleared from self each settlement (1 = 100 points, enough to empty). Default 1. Set to 0 to disable.") },
            { "区|区块链-同伴孢子", ("blockchainAllySpores", "[Blockchain] Spores added each settlement to all players within the radius except other Qu (0.025 = 2.5 points). Default 0.025. Multiple Qu do not stack: a player is added to once as long as any living Qu is within 10 meters, rather than stacking per Qu.") },
            { "区|区块链-作用半径", ("blockchainRadius", "[Blockchain] Effect radius (in meters): other players within the radius gain spores, and players within the radius with excess spores are forcibly converted to Qu. Default 10.") },
            { "区|区块链-喂食孢子", ("blockchainFeedSpores", "[Blockchain] Spores additionally added to the fed player each time a Qu feeds another player 1 Early Worm (cooked or not) (0.15 = 15 points). Default 0.15.") },
            { "区|区块链-传染启用", ("blockchainInfectEnabled", "[Blockchain] Whether players whose spore value reaches the threshold and who are within the radius are forcibly converted to Qu. Default true.") },
            { "区|区块链-传染阈值", ("blockchainInfectThreshold", "[Blockchain] Spore threshold required for infection (0.5 = 50 points). Default 0.5.") },
            { "区|区块链-奖励虫儿", ("blockchainRewardBug", "[Blockchain] Whether all Qu on the field each gain 1 Early Worm each time another player is successfully infected into a Qu. Default true.") },
            { "区|好多区-启用", ("manyQuEnabled", "[Many Qu] Whether enabled. Default true.") },
            { "区|好多区-触发次数", ("manyQuTriggerCount", "[Many Qu] For every this many triggers of [Decomposer] on self, 1 Early Worm is gained (counted separately per player). Default 5. Set to 0 to disable.") },
            { "区|好多区-间隔", ("manyQuIntervalSeconds", "[Many Qu] How often (in seconds) the worm / Qu count bonus is settled. Default 60.") },
            { "区|好多区-减饥饿", ("manyQuHungerReduction", "[Many Qu] Hunger reduced from self per worm or nearby Qu (0.025 = 2.5 points). Default 0.025.") },
            { "区|好多区-额外体力", ("manyQuExtraStamina", "[Many Qu] Extra stamina added to self per worm or nearby Qu (0.025 = 2.5 points). Default 0.025.") },
            { "区|好多区-区半径", ("manyQuQuRadius", "[Many Qu] Qu within this many meters of self also count toward the bonus (meters). Default 30.") },
            { "区|好多区-阈值半径", ("manyQuThresholdRadius", "[Many Qu] Radius (in meters) used to count the number of living Qu within own radius (including self) for the speedup / infinite stamina threshold check. Default 20. (This is a different radius from manyQuQuRadius 30m above: the latter is used to compute the number of stacks, this one to decide the speedup / infinite stamina.)") },
            { "区|好多区-最大层数", ("manyQuMaxStacks", "[Many Qu] Maximum number of stacks the bonus can accumulate. Default 4. Stacks = number of Early Worms in the inventory + number of Qu within own radius (see manyQuQuRadius) excluding self; capped at this value when exceeded (each stack = the hunger of manyQuHungerReduction plus the extra stamina of manyQuExtraStamina). Set to 0 or negative = no stack limit.") },
            { "区|好多区-加速虫儿数", ("manyQuSpeedBugCount", "[Many Qu] When the number of Early Worms in the inventory reaches this value, an extra speedup effect is granted. Default 3.") },
            { "区|好多区-加速区数", ("manyQuSpeedQuCount", "[Many Qu] When the number of living Qu within own manyQuThresholdRadius (including self) reaches this value, an extra speedup effect is granted. Default 3.") },
            { "区|好多区-无限体力区数", ("manyQuInfiniteStaminaQuCount", "[Many Qu] When the number of living Qu within own manyQuThresholdRadius (including self) reaches this value, an extra infinite stamina effect is granted. Default 4.") },
            { "区|区毒不食子-启用", ("quPoisonEnabled", "[Qu Poison] Whether enabled. Default true.") },
            { "区|区毒不食子-诅咒", ("quPoisonCurse", "[Qu Poison] Curse added to self each time a Qu eats 1 Early Worm (cooked or not) (0.10 = 10 points). Default 0.10.") },
            { "太空人|启用职业", ("enabled", "Whether to enable the Astronaut class.") },
            { "太空人|最大人数", ("maxPlayers", "Maximum number of players the Astronaut is assigned to. Set to 0 for unlimited.") },
            { "太空人|最小人数", ("minPlayers", "Minimum number of players the Astronaut is assigned to. This class is prioritized to fill up when there are too few.") },
            { "太空人|抽取权重", ("weight", "Weight of the Astronaut when randomly assigning.") },
            { "太空人|轻飘飘-初始气球数", ("floatyInitialBalloonCount", "[Floaty] Number of balloons tied to the Astronaut at the start of the run. Default 2. Set to 0 to disable the initial balloons.") },
            { "太空人|轻飘飘-间隔", ("floatyIntervalSeconds", "[Floaty] How often (in seconds) balloons are tied to this Astronaut again. Default 120 (2 minutes). Set to 0 to disable periodic balloon tying.") },
            { "太空人|轻飘飘-每次气球数", ("floatyBalloonCountPerTime", "[Floaty] Number of balloons tied to this Astronaut at each floatyIntervalSeconds. Default 2.") },
            { "太空人|轻飘飘-拾取气球消失", ("floatyBalloonPickupVanishes", "[Floaty] When the Astronaut picks up a Balloon or BalloonBunch, whether the item vanishes (does not enter the inventory). Default true. If false, pickup behaves as in vanilla.") },
            { "太空人|飞起来-启用", ("takeoffEnabled", "[Takeoff] Whether enabled. Default true.") },
            { "太空人|飞起来-火箭背包概率", ("takeoffRocketpackChance", "[Takeoff] Chance (0.20 = 20%) of an item becoming a Rocketpack on pickup. When the roll succeeds: the picked-up item vanishes and 1 Rocketpack is spawned at the feet. Default 0.20. Set to 0 to disable this branch.") },
            { "太空人|飞起来-喷气背包概率", ("takeoffJetpackChance", "[Takeoff] Chance (0.10 = 10%) of an item becoming a Jetpack on pickup. The Rocketpack branch is rolled first; this branch is rolled only if that misses. On success the picked-up item vanishes and a Jetpack is spawned at the feet. Default 0.10. Set to 0 to disable this branch.") },
            { "太空人|飞起来-对食物物品也生效", ("takeoffAffectsFoodItems", "[Takeoff] Whether food items also take part in the chance change. Default false. Requirement: picking up a non-food item (and not in the special item blacklist) has a chance to become a Rocketpack / Jetpack; picking up a food item or an item in the special item blacklist always stays unchanged and no chance roll is made. Food items = items with the Berry / Mushroom / PackagedFood tag, or CookedAmount >= 1 (cooked). Change to true only if you want even food to possibly become a backpack (this deviates from the requirement).") },
            { "太空人|飞起来-特殊物品黑名单", ("takeoffSpecialItemBlacklist", "[Takeoff] Prefab names of special items that are unaffected (never turned into a backpack), comma-separated. Default: Mushroom Glow, Rocketpack, Jetpack, Flare, Strange Gem, the Scout's Perseverance / Initiative / Hospitality / Ambition (the four amulets), the Scout's Honor ScoutsHonor.") },
            { "太空人|太空食品安全-中毒", ("spaceFoodSafetyPoison", "[Space Food Safety] Poison value added each time the Astronaut eats an unqualified food (0.10 = 10 points). Qualified = packaged food (PackagedFood tag) or cooked food (CookedAmount >= 1). Items in the blacklist are exempt and do not trigger poison (not including Mushroom Glow, Cure-All). Default 0.10. Set to 0 to disable.") },
            { "太空人|太空食品安全-黑名单", ("spaceFoodSafetyBlacklist", "[Space Food Safety] Eating these items does not trigger poison (prefab names, comma-separated). Default Mushroom Glow / Cure-All - i.e. Mushroom Glow and Cure-All are not included. Leave empty to exempt no items (Mushroom Glow and Cure-All will then also trigger poison).") },
            { "太空人|NASA-间隔", ("nasaIntervalSeconds", "[NASA] How often (in seconds) the hot / cold reduction is settled. Default 5.") },
            { "太空人|NASA-炎热", ("nasaHot", "[NASA] Hot value reduced from this Astronaut each time (0.05 = 5 points). Default 0.05. Set to 0 to disable.") },
            { "太空人|NASA-寒冷", ("nasaCold", "[NASA] Cold value reduced from this Astronaut each time (0.05 = 5 points). Default 0.05. Set to 0 to disable.") },
            { "太空人|NASA-额外增加", ("nasaExtraIncrease", "[NASA] Additional amount of the same status added each time this Astronaut gains (an increase of) cobweb / flytrap / curse (0.025 = 2.5 points). That is: for every X curse gained, an extra +2.5 curse is added; likewise for cobweb / flytrap. Default 0.025. Set to 0 to disable.") },
            { "太空人|NASA-额外增加-冷却", ("nasaExtraIncreaseCooldown", "[NASA] After each extra cobweb / flytrap / curse increase, how many seconds to skip detection and further increases (seconds). Prevents a single increase from repeating forever when the host's synced remote status lags behind. Default 1.0. Set to 0 or a negative value to disable the cooldown (old behavior).") },
            { "榔王|启用职业", ("enabled", "Whether to enable the Langwang class.") },
            { "榔王|最大人数", ("maxPlayers", "Maximum number of players the Langwang is assigned to. Set to 0 for unlimited. Default 10. (The Langwang can forcibly convert other players into Langwang through [Quit If Not Eating], making it an infectious class, so by default the player count is relaxed to 10 like Daihao / Qu, not 1.) Note: the forced conversion of [Quit If Not Eating] is not limited by this cap.") },
            { "榔王|最小人数", ("minPlayers", "Minimum number of players the Langwang is assigned to. This class is prioritized to fill up when there are too few.") },
            { "榔王|抽取权重", ("weight", "Weight of the Langwang when randomly assigning. Default 5 (an infectious class, on the same tier as Daihao / Qu and lower than the 10 of normal classes).") },
            { "榔王|精品大果-发放间隔", ("premiumBerryGrantInterval", "[Premium Berry] How often (in seconds) 1 litchi berry is granted to each Langwang. Default 100. Placed into empty slots of the 3 inventory slots first; if the inventory is full, spawned at the feet. Set to 0 to disable granting.") },
            { "榔王|精品大果-青荔莓物品", ("premiumBerryGreenLitchiItem", "[Premium Berry] Item prefab name of the green litchi berry. Default Kingberry Green (green kingberry). Eating it grants the Langwang one speedup effect.") },
            { "榔王|精品大果-青荔莓权重", ("premiumBerryGreenLitchiWeight", "[Premium Berry] Weight of drawing the green litchi berry. Default 10.") },
            { "榔王|精品大果-黄荔莓物品", ("premiumBerryYellowLitchiItem", "[Premium Berry] Item prefab name of the yellow litchi berry. Default Kingberry Yellow (yellow kingberry). Eating it grants the Langwang one infinite stamina effect.") },
            { "榔王|精品大果-黄荔莓权重", ("premiumBerryYellowLitchiWeight", "[Premium Berry] Weight of drawing the yellow litchi berry. Default 5.") },
            { "榔王|荔莓物品", ("litchiBerryItems", "Prefab names (comma-separated) treated as litchi berry in [Addiction] and [Quit If Not Eating]. Default: Kingberry Green / Kingberry Yellow / Kingberry Purple (the kingberry series). If this does not match the in-game litchi berry naming, fill in the real prefab names here (including the green / yellow litchi berry).") },
            { "榔王|上瘾-每次困倦", ("addictionDrowsyPerEat", "[Addiction] Drowsy value added each time the Langwang eats a non-litchi-berry food (0.30 = 30 points). Default 0.30. Set to 0 to disable.") },
            { "榔王|上瘾-未食用间隔", ("addictionNoEatInterval", "[Addiction] Number of seconds after the last litchi berry eaten before drowsy starts increasing continuously. Default 300.") },
